// `@types/node`'s shape: a specifier that resolves to no file on disk and is
// served entirely by an ambient `declare module` block.
declare module "ambmod" {
  export function starFn(x: number): string;
  export interface StarIface {
    a: number;
  }
  export class StarCls {
    m(): number;
  }
  // Also declared by the module that stars this one — the starrer's own
  // declaration must win (first contributor of a name).
  export function shadowed(): number;
}
